import type { ReactNode } from 'react';
import type { IntlShape } from 'react-intl';
import type { RequireAtLeastOne } from 'type-fest';

import type { Timeframe, TimeframeV2 } from '../../../core/types/time.js';
import { getTextFromNode } from '../../../filters/filter/utils/getTextFromNode.js';
import {
  _extractDisplayValueFromTimeValues,
  _getFromToValues,
  _parseValue,
} from '../../forms-core/time/timeParser.js';

/**
 * Converts the given timeframe into a human-readable display value string.
 * @internal
 */
export function _getTimeframeDisplayValueProps(
  value: Timeframe | RequireAtLeastOne<TimeframeV2> | null,
  intl: IntlShape,
  placeholder?: string,
  precision?: 'minutes' | 'seconds' | 'milliseconds',
  presetItemLabel?: ReactNode,
) {
  if (!value) {
    return { displayValue: placeholder ?? '', isInvalid: false, hint: '' };
  }

  if (presetItemLabel) {
    return {
      displayValue: getTextFromNode(presetItemLabel, intl, ''),
      isInvalid: false,
      hint: '',
    };
  }

  const { from, to } = _parseValue(value, true);
  const { valueFrom, valueTo } = _getFromToValues(value);

  return _extractDisplayValueFromTimeValues(
    from,
    to,
    intl,
    precision,
    valueFrom,
    valueTo,
  );
}
